cd /work && python3 -c "
import re,csv
rows=list(csv.DictReader(open('b3_supercon_target.csv')))
els=['O','Cu','Ba','Sr','Y','Ca','La','Bi','Fe','Nb','C','Pr','As','B','Pb','Ce','Mo','V','Zn','Ni']
def parse(s):
    d={}
    for m in re.finditer(r'([A-Z][a-z]?)([0-9.]*)',s):
        if not m.group(1): continue
        d[m.group(1)]=d.get(m.group(1),0)+(float(m.group(2)) if m.group(2) else 1.0)
    tot=sum(d.values())
    return {k:v/tot for k,v in d.items()}
data=[]
for r in rows:
    f=parse(r['composition']); data.append((r['composition'],float(r['target']),f))
data.sort(key=lambda x:abs(x[1]-90))
for c,t,f in data[:25]:
    print(round(t,2),c,{e:round(f.get(e,0),4) for e in els if f.get(e,0)>0})
"

